// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VerificationRuns) predicate.VerificationRuns {
	return predicate.VerificationRuns(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VerificationRuns) predicate.VerificationRuns {
	return predicate.VerificationRuns(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VerificationRuns) predicate.VerificationRuns {
	return predicate.VerificationRuns(sql.NotPredicates(p))
}
